function combine(n: number, k: number): number[][] {
  const result: number[][] = [];
  const path: number[] = [];

  // start — наименьшее число, которое ещё можно взять
  const backtrack = (start: number): void => {
    // Набрали k чисел — сохраняем копию пути
    if (path.length === k) {
      result.push([...path]);
      return;
    }

    // Отсечение: нужно добрать (k - path.length) чисел,
    // поэтому начинать позже, чем n - need + 1, бессмысленно
    const need = k - path.length;
    for (let x = start; x <= n - need + 1; x++) {
      path.push(x); // берём x
      backtrack(x + 1); // дальше только числа больше x — без повторов порядка
      path.pop(); // откат
    }
  };

  backtrack(1);
  return result;
}

// Время: O(C(n, k) · k) — число сочетаний, умноженное на копирование пути
// Память: O(k) на рекурсию и путь (без учёта ответа)
